__NUXT_JSONP__("/think-tanks/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o){return {data:[{columnas:[{slug:"how_four_think_tanks_are_adapting_as_core_funding_declines",title:"How four think tanks are adapting as core funding declines",date:"2026-07-16T16:04:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Ffd1a878e-aba7-491d-a1db-72a56e9cd80f\u002F","img-alt":"Financiamiento ONG",autor:"Andrea Cabrera",medio:e,link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fhow-four-think-tanks-are-adapting-as-core-funding-declines\u002F",category:a,extracto:"Diversifying income is now essential for survival, not just an option for a select few. Following USAID’s withdrawal and aid reductions, the question has shifted from “should we diversify?” to “how do we diversify?”",toc:[{id:"acknowledging-the-risks",depth:d,text:"Acknowledging the risks"},{id:"effective-strategies",depth:d,text:"Effective strategies"}],dir:b,path:"\u002Fcolumnas\u002Fhow_four_think_tanks_are_adapting_as_core_funding_declines",extension:c,createdAt:"2026-07-19T00:56:17.187Z",updatedAt:"2026-07-19T00:56:17.188Z"},{slug:"financiamiento_internacional_nuevas_reglas_con_intereses_para_la_sociedad_civil",title:"Financiamiento internacional: nuevas reglas, con intereses, para la sociedad civil",date:"2026-07-01T18:56:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F92d30266-cd9e-40de-b125-afeee0951409\u002F",autor:"Emiliano Montes de Oca",medio:f,link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Ffinanciamiento-internacional-nuevas-reglas?shem=isphc,",category:a,extracto:"El financiamiento internacional responde cada vez menos a prioridades universales y cada vez más a intereses estratégicos de los países y actores que aportan los recursos. La cooperación no ha desaparecido, pero se ha vuelto más geopolítica.",toc:[{id:"recursos-para-desafíos-reales-y-urgentes",depth:d,text:"Recursos para desafíos reales y urgentes"},{id:"entonces-cómo-obtener-los-recursos",depth:d,text:"¿Entonces cómo obtener los recursos?"}],dir:b,path:"\u002Fcolumnas\u002Ffinanciamiento_internacional_nuevas_reglas_con_intereses_para_la_sociedad_civil",extension:c,createdAt:h,updatedAt:h},{slug:"el_legado_de_usaid_a_un_ano_de_su_cierre_el_vacio_que_deja_en_mexico_y_el_mundo",title:"El legado de USAID a un año de su cierre: el vacío que deja en México y el mundo",date:"2026-03-27T15:19:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F20b8de8c-b896-4726-92c2-6103843a2309\u002F","img-alt":"Cierre de USAID",autor:"Brandon Fischer",medio:f,link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Fusaid-cierre-legado-cooperacion-internacional-mexico",category:a,extracto:"La pregunta hoy no es si USAID fue una institución ideal —no lo fue—, sino qué tipo de cooperación queremos construir en su ausencia, porque el desarrollo es, ante todo, una red de personas que creen que el mundo puede ser más justo.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fel_legado_de_usaid_a_un_ano_de_su_cierre_el_vacio_que_deja_en_mexico_y_el_mundo",extension:c,createdAt:i,updatedAt:i},{slug:"la_sociedad_civil_global_en_la_hora_de_la_incertidumbre",title:"La sociedad civil global, en la hora de la incertidumbre",date:"2026-03-23T22:19:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F9944367b-b3b0-4a8a-a4dc-0b894724594a\u002F","img-alt":"Sociedad civil",autor:j,medio:"Este País",link:"https:\u002F\u002Festepais.com\u002Ftendencias_y_opiniones\u002Fsociedad-civil-global\u002F",category:a,extracto:"Javier González, de Ethos Innovación en Políticas Públicas, aborda los desafíos de la sociedad civil global ante la incertidumbre, los retrocesos democráticos y la necesidad de replantear su estrategia.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fla_sociedad_civil_global_en_la_hora_de_la_incertidumbre",extension:c,createdAt:k,updatedAt:k},{slug:"collaboration_under_the_mantle_of_populism",title:"Collaboration under the mantle of populism",date:"2025-07-10T17:20:20.737Z",img:"https:\u002F\u002Fucarecdn.com\u002F2c75323d-b65f-4d5a-8e29-fa2c0b7f4977\u002F","img-alt":"colaboración",autor:"Liliana Alvarado ",medio:e,link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fcollaboration-under-the-mantle-of-populism\u002F",category:a,extracto:"The radicalisation and polarisation of perspectives hinder dialogue and consensus-building. This growing divide among actors is not only present in populist governments but also in other regimes undergoing processes of democratic backsliding, where core values such as freedom of expression, civic participation, the rule of law, and tolerance are increasingly undermined.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fcollaboration_under_the_mantle_of_populism",extension:c,createdAt:l,updatedAt:l},{slug:"la_colaboracion_bajo_el_manto_populista",title:"La colaboración bajo el manto populista",date:"2025-05-19T17:35:15.354Z",img:"https:\u002F\u002Fucarecdn.com\u002F1caf6dd2-6613-4c30-b702-bdcf76cda551\u002F","img-alt":"Think Tanks",autor:"Liliana Alvarado",medio:f,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fcolaboracion-manto-populista",category:a,extracto:"Resulta difícil predecir cuál es el futuro de la colaboración bajo el manto populista, el cual cobija con sus preceptos a cada vez más personas en el mundo. En ese contexto, los think tanks deben encontrar cómo influir sin ceder sus principios ni legitimar posturas que están erosionando a los regímenes democráticos.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fla_colaboracion_bajo_el_manto_populista",extension:c,createdAt:m,updatedAt:m},{slug:"mexico_between_fragility_and_adaptability",title:"Mexico | Between fragility and adaptability",date:"2024-12-05T21:51:27.281Z",img:"https:\u002F\u002Fucarecdn.com\u002F58ea9438-6430-4f25-9980-d0b5586d99a6\u002F","img-alt":"State of the sector On Think Tanks",autor:j,medio:e,link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fthink-tanks-mexico-fragility\u002F",category:a,extracto:"In this blog, I will briefly analyse how the political context has significantly influenced the scope and nature of the work carried out by Mexican think tanks.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fmexico_between_fragility_and_adaptability",extension:c,createdAt:n,updatedAt:n},{slug:"the_global_south_perspective_through_g20_recommendations_from_the_think_tank_20",title:"The Global South perspective through G20: recommendations from the Think Tank 20",date:"2024-07-22T21:24:44.297Z",img:"https:\u002F\u002Fucarecdn.com\u002F1a583a81-bf17-45ee-8238-284d468c3861\u002F",autor:"Javier González y José Francisco García",medio:"Southern Voice",link:"https:\u002F\u002Fsouthernvoice.org\u002Fthe-global-south-perspective-through-g20-recommendations-from-the-think-tank-20\u002F",category:a,extracto:"In this piece, we aim to outline the recommendations  of the Think Tank 20 (T20) engagement group to G20 leaders and negotiators, which were formally issued in the T20 2024 Communiqué during the Midterm Conference on July 2nd and 3rd 2024.",toc:[{id:"combating-poverty-hunger-and-inequality",depth:g,text:"Combating poverty, hunger and inequality"},{id:"on-sustainable-climate-action-and-inclusive-just-energy-transitions",depth:g,text:"On sustainable climate action and inclusive just energy transitions"},{id:"final-remarks",depth:g,text:"Final Remarks"}],dir:b,path:"\u002Fcolumnas\u002Fthe_global_south_perspective_through_g20_recommendations_from_the_think_tank_20",extension:c,createdAt:o,updatedAt:o}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("think-tanks","\u002Fcolumnas",".md",3,"On Think Tanks","Animal Político",2,"2026-07-19T00:56:17.186Z","2026-07-19T00:56:17.184Z","Javier González","2026-07-19T00:56:17.190Z","2025-11-25T01:24:03.234Z","2025-11-25T01:24:03.243Z","2025-04-23T06:21:15.370Z","2024-10-02T22:32:44.076Z")));